query:
SELECT 'molecules' as type, id, name FROM molecules WHERE name LIKE '%Linalol%' OR name LIKE '%Myrcene%' OR name LIKE '%Limonene%' OR name LIKE '%Pinene%' OR name LIKE '%Caryophyllene%'
UNION ALL
SELECT 'plants' as type, id, name FROM plants;

